<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { get } from 'svelte/store';
  import { gsap } from 'gsap';
  import { getCameras, uploadFrame, type BackendCamera } from '../../lib/api';
  import { cameraAssignments, cameraViews, sessionId, setCaptureViews, type CameraQuality, type CameraView, type CaptureView, type SavedCameraAssignment } from '../../lib/stores/session';

  let { onExit = () => {}, onActivity = () => {} }: { onExit?: () => void; onActivity?: () => void } = $props();
  interface CameraOption { id: string; label: string; displayLabel: string; groupId: string; shortId: string; }
  type SlotStatus = 'not-used' | 'starting' | 'live' | 'no-signal' | 'in-use' | 'error';
  interface Slot extends SavedCameraAssignment { status: SlotStatus; message: string; errorName: string; stream: MediaStream | null; width: number | null; height: number | null; fps: number | null; mirrored: boolean; bodyDetected: boolean; sequence: number; groupId: string; trackState: string; firstFrameMs: number | null; }
  interface Profile { width?: number; height?: number; fps?: number; }
  type FrameVideo = HTMLVideoElement & { requestVideoFrameCallback?: (callback: () => void) => number; };

  const labels: Record<CameraView, string> = { left: 'LEFT', back: 'BACK', right: 'RIGHT' };
  const emptySlot = (saved?: SavedCameraAssignment): Slot => ({ deviceId: saved?.deviceId ?? null, rotation: saved?.rotation ?? 0, quality: saved?.quality ?? 'auto', status: saved?.deviceId ? 'starting' : 'not-used', message: '', errorName: '', stream: null, width: null, height: null, fps: null, mirrored: false, bodyDetected: false, sequence: 0, groupId: '', trackState: '—', firstFrameMs: null });
  const saved = get(cameraAssignments);
  let slots = $state<Record<CameraView, Slot>>({ left: emptySlot(saved.left), back: emptySlot(saved.back), right: emptySlot(saved.right) });
  let cameras = $state<CameraOption[]>([]);
  let backendCameras = $state<BackendCamera[]>([]);
  let loading = $state(true);
  let error = $state('');
  let note = $state('');
  let previewNodes: Partial<Record<CameraView, HTMLVideoElement>> = {};
  let inspectionTimer: ReturnType<typeof setInterval> | undefined;
  let handingOff = false;
  let scannedOnce = false;
  let scanning = false;
  const canvasByView: Partial<Record<CameraView, HTMLCanvasElement>> = {};

  const delay = (ms: number) => new Promise<void>((resolve) => window.setTimeout(resolve, ms));
  const activeSlots = () => cameraViews.filter((view) => slots[view].stream && slots[view].status === 'live');
  const device = (id: string | null) => cameras.find((camera) => camera.id === id);
  const deviceLabel = (id: string | null) => device(id)?.displayLabel ?? 'Not used';
  const assignedElsewhere = (view: CameraView, id: string) => cameraViews.some((other) => other !== view && slots[other].deviceId === id);
  function errorInfo(failure: unknown) {
    const name = failure instanceof DOMException ? failure.name : failure instanceof Error ? failure.name : 'CameraError';
    const detail = failure instanceof Error ? failure.message : 'Camera could not start.';
    const hints: Record<string, string> = { NotAllowedError: 'Camera permission was denied. Allow access in your browser settings.', NotReadableError: 'The camera is in use or USB bandwidth is limited. Close another camera app, try 480p30, or use a powered hub.', OverconstrainedError: 'That resolution or frame rate is not supported. GAIT will try a lower setting.', AbortError: 'The camera was interrupted while starting. Retry this view.', NotFoundError: 'This camera is no longer connected. Rescan after reconnecting it.' };
    return { name, detail, hint: hints[name] ?? detail };
  }
  function persist() { cameraAssignments.set(cameraViews.reduce((out, view) => { const slot = slots[view]; out[view] = { deviceId: slot.deviceId, rotation: slot.rotation, quality: slot.quality }; return out; }, {} as Record<CameraView, SavedCameraAssignment>)); }
  function attach(view: CameraView) { const video = previewNodes[view], stream = slots[view].stream; if (!video || !stream) return; video.muted = true; video.playsInline = true; video.autoplay = true; video.srcObject = stream; void video.play().catch(() => {}); }
  function previewVideo(node: HTMLVideoElement, view: CameraView) { previewNodes[view] = node; attach(view); return { destroy() { if (previewNodes[view] === node) delete previewNodes[view]; } }; }
  function releaseSlot(view: CameraView, keepAssignment = false) { const current = slots[view]; current.stream?.getTracks().forEach((track) => track.stop()); const video = previewNodes[view]; if (video) { video.pause(); video.srcObject = null; } slots[view] = { ...emptySlot(keepAssignment ? current : undefined), deviceId: keepAssignment ? current.deviceId : null, rotation: current.rotation, quality: current.quality }; }
  function profilesFor(quality: CameraQuality, assignedCount: number): Profile[] { if (quality === '720p30') return [{ width: 1280, height: 720, fps: 30 }, { width: 640, height: 480, fps: 30 }, {}]; if (quality === '480p30') return [{ width: 640, height: 480, fps: 30 }, { width: 640, height: 360, fps: 15 }, {}]; if (quality === '360p15') return [{ width: 640, height: 360, fps: 15 }, {}]; return assignedCount >= 3 ? [{ width: 640, height: 480, fps: 30 }, { width: 640, height: 360, fps: 15 }, {}] : [{ width: 1280, height: 720, fps: 30 }, { width: 640, height: 480, fps: 30 }, {}]; }
  function constraintsFor(id: string, profile: Profile): MediaStreamConstraints { return { video: { deviceId: { exact: id }, ...(profile.width ? { width: { ideal: profile.width } } : {}), ...(profile.height ? { height: { ideal: profile.height } } : {}), ...(profile.fps ? { frameRate: { ideal: profile.fps } } : {}) }, audio: false }; }
  async function waitForFirstFrame(video: HTMLVideoElement): Promise<void> {
    if (video.readyState < HTMLMediaElement.HAVE_METADATA) await new Promise<void>((resolve, reject) => { const timeout = window.setTimeout(() => { cleanup(); reject(new Error('No video metadata after 3 seconds.')); }, 3000); const loaded = () => { cleanup(); resolve(); }; const failed = () => { cleanup(); reject(new Error('Video element could not load the stream.')); }; const cleanup = () => { clearTimeout(timeout); video.removeEventListener('loadedmetadata', loaded); video.removeEventListener('error', failed); }; video.addEventListener('loadedmetadata', loaded, { once: true }); video.addEventListener('error', failed, { once: true }); });
    await video.play().catch(() => {});
    await new Promise<void>((resolve, reject) => { const timeout = window.setTimeout(() => reject(new Error('No video signal after 3 seconds.')), 3000); const finish = () => { clearTimeout(timeout); resolve(); }; const frameVideo = video as FrameVideo; if (frameVideo.requestVideoFrameCallback) frameVideo.requestVideoFrameCallback(() => finish()); else if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) finish(); else video.addEventListener('loadeddata', finish, { once: true }); });
  }
  async function maybeUseSingleCamera60(track: MediaStreamTrack, _view: CameraView) { if (cameraViews.filter((candidate) => slots[candidate].deviceId).length !== 1) return; const capabilities = track.getCapabilities?.() as { frameRate?: { max?: number } } | undefined; if ((capabilities?.frameRate?.max ?? 0) < 60) return; try { await track.applyConstraints({ frameRate: { ideal: 60 } }); } catch { /* 30 FPS remains the safe default. */ } }
  async function openSlot(view: CameraView, preferLower = false) {
    const assigned = slots[view].deviceId, quality = slots[view].quality;
    if (!assigned) return;
    releaseSlot(view, true); slots[view] = { ...slots[view], status: 'starting', message: '', errorName: '' }; await tick();
    const startedAt = performance.now(); let lastFailure: unknown; const profiles = profilesFor(quality, cameraViews.filter((candidate) => slots[candidate].deviceId).length); if (preferLower && profiles.length > 1) profiles.splice(0, 1);
    for (const profile of profiles) { let stream: MediaStream | null = null; try {
      stream = await navigator.mediaDevices.getUserMedia(constraintsFor(assigned, profile)); const track = stream.getVideoTracks()[0]; if (!track) throw new Error('The browser returned no video track.'); const selected = device(assigned);
      slots[view] = { ...slots[view], stream, status: 'starting', width: null, height: null, fps: null, groupId: selected?.groupId ?? '', trackState: track.readyState, mirrored: track.getSettings().facingMode === 'user' || /front|facetime|integrated|user/i.test(selected?.label ?? '') }; attach(view);
      const video = previewNodes[view]; if (!video) throw new Error('Preview element is not mounted.'); await waitForFirstFrame(video); await maybeUseSingleCamera60(track, view); const settings = track.getSettings();
      slots[view] = { ...slots[view], status: 'live', width: settings.width ?? profile.width ?? null, height: settings.height ?? profile.height ?? null, fps: settings.frameRate ?? profile.fps ?? null, trackState: track.readyState, firstFrameMs: Math.round(performance.now() - startedAt) };
      track.addEventListener('ended', () => { if (slots[view].stream === stream) slots[view] = { ...slots[view], stream: null, status: 'error', errorName: 'TrackEnded', trackState: 'ended', message: 'Camera stream ended. Try another USB port or a powered hub; the other views remain active.' }; });
      track.addEventListener('mute', () => { if (slots[view].stream === stream) slots[view].trackState = 'muted'; }); track.addEventListener('unmute', () => { if (slots[view].stream === stream) slots[view].trackState = track.readyState; }); persist(); return;
    } catch (failure) { stream?.getTracks().forEach((track) => track.stop()); lastFailure = failure; } }
    const failure = errorInfo(lastFailure), noSignal = /No video signal|No video metadata|could not load/i.test(failure.detail);
    slots[view] = { ...slots[view], status: noSignal ? 'no-signal' : failure.name === 'NotReadableError' ? 'in-use' : 'error', errorName: failure.name, message: noSignal ? 'No video signal. Retrying at a lower quality may help.' : failure.hint, trackState: 'ended' }; error = `${labels[view]}: ${failure.name} — ${failure.hint}`;
  }
  async function openAssignedSlots() { for (const view of cameraViews) { if (!slots[view].deviceId || slots[view].status === 'live') continue; await delay(400); await openSlot(view); } }
  async function setDevice(view: CameraView, id: string) { if (!id) { releaseSlot(view); persist(); return; } const conflict = cameraViews.find((other) => other !== view && slots[other].deviceId === id); if (conflict) { releaseSlot(conflict); note = `${labels[conflict]} was released so this camera can be used for ${labels[view]}.`; } releaseSlot(view); slots[view] = { ...slots[view], deviceId: id, status: 'starting' }; persist(); await delay(400); await openSlot(view); }
  async function setQuality(view: CameraView, quality: CameraQuality) { slots[view] = { ...slots[view], quality }; persist(); if (slots[view].deviceId) await openSlot(view, quality === '480p30' || quality === '360p15'); }
  function rotate(view: CameraView) { slots[view] = { ...slots[view], rotation: (slots[view].rotation + 90) % 360 }; persist(); }
  function uniqueDevices(devices: MediaDeviceInfo[]): CameraOption[] {
    const deviceIds = new Set<string>(), groupIds = new Set<string>();
    const raw = devices.filter((item) => item.deviceId && !deviceIds.has(item.deviceId)).sort((a, b) => {
      const rank = (item: MediaDeviceInfo) => /integrated|built-in|builtin|internal|laptop|hp hd camera/i.test(item.label) ? 1 : 0;
      return rank(a) - rank(b) || `${a.label}|${a.groupId}|${a.deviceId}`.localeCompare(`${b.label}|${b.groupId}|${b.deviceId}`);
    });
    const ungrouped = raw.filter((item) => { if (deviceIds.has(item.deviceId) || (item.groupId && groupIds.has(item.groupId))) return false; deviceIds.add(item.deviceId); if (item.groupId) groupIds.add(item.groupId); return true; });
    const counts = new Map<string, number>(), occurrence = new Map<string, number>(); ungrouped.forEach((item, index) => { const label = item.label || `Camera ${index + 1}`; counts.set(label, (counts.get(label) ?? 0) + 1); });
    return ungrouped.map((item, index) => { const label = item.label || `Camera ${index + 1}`, itemNumber = (occurrence.get(label) ?? 0) + 1; occurrence.set(label, itemNumber); return { id: item.deviceId, label, displayLabel: (counts.get(label) ?? 0) > 1 ? `${label} (${itemNumber})` : label, groupId: item.groupId, shortId: item.deviceId.slice(-6) }; });
  }
  function assignInitialSlots() { if (scannedOnce) return; scannedOnce = true; const alreadyAssigned = new Set(cameraViews.map((view) => slots[view].deviceId).filter(Boolean) as string[]); for (const view of cameraViews) { if (slots[view].deviceId) continue; const next = cameras.find((candidate) => !alreadyAssigned.has(candidate.id)); if (!next) break; slots[view] = { ...slots[view], deviceId: next.id, groupId: next.groupId, status: 'starting' }; alreadyAssigned.add(next.id); } persist(); }
  async function discover(requestPermission = false, openAfter = false) {
    if (scanning) return; scanning = true; loading = true; error = '';
    try { if (!navigator.mediaDevices?.enumerateDevices) throw new Error('Camera discovery is not supported in this browser.'); let permission: MediaStream | null = null; if (requestPermission) { try { permission = await navigator.mediaDevices.getUserMedia({ video: true, audio: false }); } finally { permission?.getTracks().forEach((track) => track.stop()); } }
      cameras = uniqueDevices((await navigator.mediaDevices.enumerateDevices()).filter((item) => item.kind === 'videoinput')); backendCameras = await getCameras().catch(() => []);
      for (const view of cameraViews) if (slots[view].deviceId && !cameras.some((camera) => camera.id === slots[view].deviceId)) { releaseSlot(view, true); slots[view] = { ...slots[view], status: 'error', errorName: 'NotFoundError', message: 'Camera was disconnected. Reconnect it and rescan.' }; }
      assignInitialSlots(); note = cameras.length < 2 ? 'Only one browser camera is available. Some phones and tablets permit one stream at a time.' : ''; await tick(); gsap.from('.view-slot', { y: 18, opacity: 0, duration: .42, stagger: .07, ease: 'power3.out', overwrite: 'auto' }); if (openAfter) await openAssignedSlots();
    } catch (failure) { error = errorInfo(failure).hint; } finally { loading = false; scanning = false; }
  }
  async function inspect() { const session = get(sessionId); if (!session) return; for (const view of activeSlots()) { const video = previewNodes[view], slot = slots[view]; if (!video || video.readyState < HTMLMediaElement.HAVE_CURRENT_DATA) continue; const canvas = canvasByView[view] ?? (canvasByView[view] = document.createElement('canvas')); canvas.width = 480; canvas.height = 270; canvas.getContext('2d')?.drawImage(video, 0, 0, canvas.width, canvas.height); canvas.toBlob(async (blob) => { if (!blob) return; try { const response = await uploadFrame(session, blob, { view, seq: slot.sequence++, timestampMs: performance.now() }); slots[view] = { ...slots[view], bodyDetected: response.bodyDetected ?? false }; } catch { /* Activity recording surfaces backend errors; previews stay responsive. */ } }, 'image/jpeg', .65); } }
  function diagnostics() { return { createdAt: new Date().toISOString(), browserVideoInputs: cameras.length, backendCaptureCameras: backendCameras.length, browser: cameras.map((camera) => ({ label: camera.displayLabel, deviceId: camera.shortId, groupId: camera.groupId ? camera.groupId.slice(-6) : null })), backend: backendCameras.map((camera) => ({ label: camera.label, node: camera.node ?? camera.id, modes: camera.modes ?? [] })), slots: cameraViews.map((view) => { const slot = slots[view]; return { view, label: deviceLabel(slot.deviceId), deviceId: slot.deviceId?.slice(-6) ?? null, groupId: slot.groupId ? slot.groupId.slice(-6) : null, status: slot.status, resolution: slot.width && slot.height ? `${slot.width}x${slot.height}` : null, fps: slot.fps, trackState: slot.trackState, firstFrameMs: slot.firstFrameMs, error: slot.errorName || null, message: slot.message || null }; }) }; }
  async function copyDiagnostics() { try { await navigator.clipboard.writeText(JSON.stringify(diagnostics(), null, 2)); note = 'Camera diagnostics copied.'; } catch { note = 'Clipboard access was blocked. Open this panel and copy the details manually.'; } }
  function continueToActivity() { const selected: Partial<Record<CameraView, CaptureView>> = {}; activeSlots().forEach((view) => { const slot = slots[view]; selected[view] = { view, deviceId: slot.deviceId!, label: deviceLabel(slot.deviceId), stream: slot.stream!, rotation: slot.rotation, width: slot.width, height: slot.height, fps: slot.fps, mirrored: slot.mirrored }; }); if (!Object.keys(selected).length) { error = 'Assign and start at least one camera before continuing.'; return; } handingOff = true; setCaptureViews(selected); onActivity(); }
  function exit() { cameraViews.forEach((view) => releaseSlot(view)); setCaptureViews({}); onExit(); }
  const onDeviceChange = () => void discover(false, true);
  onMount(() => { void discover(true, true); inspectionTimer = setInterval(() => void inspect(), 650); navigator.mediaDevices?.addEventListener('devicechange', onDeviceChange); return () => { if (inspectionTimer) clearInterval(inspectionTimer); navigator.mediaDevices?.removeEventListener('devicechange', onDeviceChange); if (!handingOff) exit(); }; });
</script>

<main class="gait-test-shell">
  <header class="gait-topbar"><button class="gait-wordmark" onclick={exit}>GAIT<span>®</span></button><p>Step 1 / <b>Choose your camera views</b></p><button class="exit-button" onclick={exit}>Exit test <span>↗</span></button></header>
  <section class="gait-panel" aria-labelledby="camera-title">
    <div class="select-intro"><p class="section-kicker">Every angle earns its place.</p><h1 id="camera-title">Set your<br />views.</h1><p>Assign LEFT, BACK, and RIGHT camera views. Cameras open one at a time to preserve USB bandwidth. We process movement landmarks, never raw camera images.</p></div>
    <div class="tools"><button class="rescan" onclick={() => void discover(true, true)} disabled={loading}>{loading ? 'SCANNING…' : 'RESCAN CAMERAS'}</button></div>
    <div class="view-grid" aria-live="polite">{#each cameraViews as view}{@const slot = slots[view]}<article class:live={slot.status === 'live'} class:error={slot.status === 'error' || slot.status === 'in-use' || slot.status === 'no-signal'} class="view-slot"><header><strong>{labels[view]}</strong><span class:ok={slot.status === 'live'} class:warn={slot.status === 'no-signal' || slot.status === 'in-use'}>{slot.status === 'live' ? 'LIVE' : slot.status.replace('-', ' ').toUpperCase()}</span></header><div class="preview-frame" style={`--rotation:${slot.rotation}deg`}><video use:previewVideo={view} autoplay muted playsinline class:mirrored={slot.mirrored}></video>{#if !slot.stream}<span>{slot.status === 'no-signal' ? 'No video signal' : 'Camera preview'}</span>{/if}{#if slot.bodyDetected}<i>BODY FOUND</i>{/if}</div><label>Camera<select value={slot.deviceId ?? ''} onchange={(event) => void setDevice(view, event.currentTarget.value)}><option value="">Not used</option>{#each cameras as camera}<option value={camera.id} disabled={assignedElsewhere(view, camera.id)}>{camera.displayLabel} · {camera.shortId}</option>{/each}</select></label><div class="slot-controls"><label>Quality<select value={slot.quality} onchange={(event) => void setQuality(view, event.currentTarget.value as CameraQuality)}><option value="auto">Auto</option><option value="720p30">720p30</option><option value="480p30">480p30</option><option value="360p15">360p15</option></select></label><button onclick={() => rotate(view)} disabled={!slot.deviceId} aria-label={`Rotate ${labels[view]} 90 degrees`}>↻ {slot.rotation}°</button></div><div class="slot-actions"><button onclick={() => void openSlot(view, true)} disabled={!slot.deviceId || slot.status === 'starting'}>RETRY</button><span>{slot.width && slot.height ? `${slot.width} × ${slot.height} · ${Math.round(slot.fps ?? 0)} FPS` : '—'}</span></div><footer>{slot.message || (slot.status === 'live' ? `First frame in ${slot.firstFrameMs ?? 0} ms · Track ${slot.trackState}` : 'Select a camera to activate this view.')}</footer></article>{/each}</div>
    <div class="bottom-row"><div>{#if note}<p>{note}</p>{/if}{#if error}<p class="error-message">{error}</p>{/if}</div><button class="continue" onclick={continueToActivity} disabled={!activeSlots().length}>START LIVE DETECTION <span>→</span></button></div>
  </section>
</main>

<style>
  .gait-test-shell{min-height:100svh;padding:0 clamp(18px,3vw,42px) 42px;background:var(--paper);color:var(--ink)}.gait-topbar{height:86px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center}.gait-wordmark,.exit-button,.rescan,.slot-controls button,.slot-actions button,.debug-tools button{border:0;background:none;color:inherit;padding:0;font-weight:800}.gait-wordmark{font-size:21px;letter-spacing:-.1em}.gait-wordmark span,.continue span{color:var(--cyan);font-size:11px}.gait-topbar p{margin:0;font-size:12px;color:var(--muted)}.exit-button{justify-self:end}.gait-panel{max-width:1320px;margin:0 auto;padding:clamp(38px,6vw,85px) 0}.select-intro{display:grid;grid-template-columns:.9fr 1.5fr;gap:36px;align-items:end;margin-bottom:30px}.section-kicker{grid-column:1/-1;margin:0;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.09em}.select-intro h1{margin:0;font-size:clamp(56px,8vw,114px);line-height:.8;letter-spacing:-.1em}.select-intro>p:last-child{max-width:510px;margin:0;color:var(--muted);line-height:1.65}.tools{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px;color:var(--muted);font-size:10px;font-weight:700}.rescan{border:1px solid #aebabc;padding:9px 11px}.rescan:disabled{opacity:.5}.view-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.view-slot{padding:14px;background:#e7eeee;min-width:0}.view-slot.live{background:#dff8ff}.view-slot.error{background:#ffe9e4}.view-slot header,.slot-controls,.bottom-row,.slot-actions{display:flex;justify-content:space-between;gap:10px;align-items:center}.view-slot header strong{font-size:13px;letter-spacing:.08em}.view-slot header span{font-size:9px;font-weight:800;color:#728084}.view-slot header .ok{color:#137d67}.view-slot header .warn{color:#af4517}.preview-frame{position:relative;display:grid;place-items:center;aspect-ratio:9/14;margin:14px 0;background:#07171c;color:#9eb3b8;overflow:hidden}.preview-frame video{width:100%;height:100%;object-fit:cover;transform:rotate(var(--rotation));scale:1.22}.preview-frame video.mirrored{transform:rotate(var(--rotation)) scaleX(-1)}.preview-frame i{position:absolute;right:8px;bottom:8px;padding:5px 6px;background:#07171ccc;color:#64f0c3;font-size:8px;font-style:normal;font-weight:800}.view-slot label{display:grid;gap:5px;margin-top:9px;color:var(--muted);font-size:10px;font-weight:800}.view-slot select{width:100%;border:1px solid #aebabc;background:#f8f8f6;color:var(--ink);padding:9px;font:inherit}.slot-controls button{border:1px solid #aebabc;padding:9px;font-weight:800}.slot-controls label{flex:1}.slot-actions{margin-top:11px;font-size:10px;color:var(--muted);font-weight:700}.slot-actions button{padding:6px 0;color:var(--ink);letter-spacing:.05em}.slot-actions button:disabled{opacity:.35}.view-slot footer{min-height:30px;margin-top:7px;color:var(--muted);font-size:10px;line-height:1.4}.debug-panel{margin-top:22px;border-top:1px solid #b4c1c3;border-bottom:1px solid #b4c1c3}.debug-panel summary{cursor:pointer;display:flex;justify-content:space-between;padding:14px 0;font-size:11px;font-weight:800;letter-spacing:.06em}.debug-panel summary span{color:var(--muted)}.debug-content{padding:0 0 16px}.debug-tools{display:flex;justify-content:space-between;gap:16px;align-items:center}.debug-tools p,.mismatch{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.debug-tools button{border:1px solid #aebabc;padding:8px 10px;font-size:9px}.mismatch{margin-top:10px;color:#99511f}.debug-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}.debug-grid section{padding:11px;background:#edf1f0;font-size:10px}.debug-grid dl{display:grid;grid-template-columns:auto 1fr;gap:5px 9px;margin:9px 0 0}.debug-grid dt{color:var(--muted)}.debug-grid dd{margin:0;overflow-wrap:anywhere}.bottom-row{margin-top:25px;padding-top:17px;border-top:1px solid #b4c1c3}.bottom-row p{margin:0;color:var(--muted);font-size:12px}.error-message{margin-top:6px!important;color:#902917!important}.continue{border:0;background:var(--ink);color:#f8f8f6;padding:15px 18px;font-weight:800}.continue:disabled{opacity:.4;cursor:not-allowed}@media(max-width:850px){.view-grid,.debug-grid{grid-template-columns:repeat(2,1fr)}.select-intro{grid-template-columns:1fr;gap:22px}.select-intro h1{max-width:500px}}@media(max-width:560px){.gait-topbar{grid-template-columns:1fr auto}.gait-topbar p{display:none}.view-grid,.debug-grid{grid-template-columns:1fr}.view-slot{display:grid;grid-template-columns:1fr 1fr;gap:10px}.view-slot header,.preview-frame,.view-slot footer,.slot-actions{grid-column:1/-1}.preview-frame{aspect-ratio:16/10;margin:0}.view-slot label{margin:0}.tools,.bottom-row,.debug-tools{align-items:flex-start;flex-direction:column}.continue{width:100%}}
</style>
